static void *xmalloc(size_t n) {
    void *p = malloc(n ? n : 1);
    if (!p) { perror("malloc"); exit(1); }
    return p;
}
static void *xrealloc(void *p, size_t n) {
    void *q = realloc(p, n ? n : 1);
    if (!q) { perror("realloc"); exit(1); }
    return q;
}
static char *xstrdup(const char *s) {
    char *r = strdup(s ? s : "");
    if (!r) { perror("strdup"); exit(1); }
    return r;
}

static void load_zstd(void) {
    if (Z.so) return;
    Z.so = dlopen("libzstd.so.1", RTLD_LAZY);
    if (!Z.so) Z.so = dlopen("libzstd.so", RTLD_LAZY);
    if (!Z.so) { fprintf(stderr, "zstd: error loading libzstd: %s\n", dlerror()); exit(1); }
