struct opts {
    int decompress, stdout_mode, force, quiet, verbose, rm, test, list;
    int level, checksum, format_gzip, ultra, pass_through, progress;
    char *output;
    struct strv files;
};

static void msgerr(const struct opts *o, const char *fmt, ...) {
    if (o && o->quiet >= 2) return;
    va_list ap; va_start(ap, fmt); vfprintf(stderr, fmt, ap); va_end(ap);
}

static int read_all_stream(FILE *f, struct buf *b) {
    b->p=NULL; b->n=0; size_t cap=0;
    for (;;) {
        if (b->n == cap) { cap = cap ? cap*2 : 65536; b->p=xrealloc(b->p, cap); }
        size_t r=fread(b->p+b->n,1,cap-b->n,f); b->n += r;
        if (r==0) { if (ferror(f)) return -1; break; }
    }
    return 0;
}
static int read_file(const char *name, struct buf *b, const struct opts *o) {
    if (strcmp(name,"-")==0) return read_all_stream(stdin,b);
    FILE *f=fopen(name,"rb");
    if(!f){ msgerr(o,"zstd: can't stat %s : No such file or directory -- ignored \n", name); return -1; }
    int rc=read_all_stream(f,b); fclose(f); if(rc) msgerr(o,"zstd: %s: read error \n", name); return rc;
}
static int write_file_all(const char *name, const unsigned char *p, size_t n, const struct opts *o) {
    if (strcmp(name,"-")==0) { if (n && fwrite(p,1,n,stdout)!=n) return -1; return fflush(stdout)==0?0:-1; }
    if (!o->force) {
        struct stat st; if (stat(name,&st)==0) { msgerr(o,"zstd: %s already exists; overwrite (y/n) ? Not overwritten  \n \n", name); return -2; }
    }
    FILE *f=fopen(name,"wb"); if(!f){ msgerr(o,"zstd: %s: %s\n", name, strerror(errno)); return -1; }
    int rc = (n==0 || fwrite(p,1,n,f)==n) ? 0 : -1;
    if (fclose(f)!=0) rc=-1;
    if(rc) msgerr(o,"zstd: %s: write error\n", name);
    return rc;
}

/* zstd parameter numbers from the stable public API. */
enum { ZSTD_c_compressionLevel = 100, ZSTD_c_checksumFlag = 201 };

static int zstd_compress_buf(const unsigned char *src, size_t srcn, int level, int checksum, struct buf *out) {
    load_zstd();
    ZSTD_CCtx *c = Z.createCCtx(); if(!c) return -1;
    size_t r = Z.CCtx_setParameter(c, ZSTD_c_compressionLevel, level); if(Z.isError(r)) { Z.freeCCtx(c); return -1; }
    r = Z.CCtx_setParameter(c, ZSTD_c_checksumFlag, checksum ? 1 : 0); if(Z.isError(r)) { Z.freeCCtx(c); return -1; }
    size_t cap = Z.compressBound(srcn); out->p=xmalloc(cap); out->n=0;
    r = Z.compress2(c, out->p, cap, src, srcn);
    Z.freeCCtx(c);
    if(Z.isError(r)) { free(out->p); out->p=NULL; return -1; }
    out->n = r; return 0;
}

static int zstd_decompress_buf(const unsigned char *src, size_t srcn, struct buf *out, const char **errname) {
    load_zstd(); out->p=NULL; out->n=0; size_t cap=0;
    ZSTD_DStream *d = Z.createDStream(); if(!d) return -1;
    size_t r = Z.initDStream(d); if(Z.isError(r)) { if(errname)*errname=Z.getErrorName(r); Z.freeDStream(d); return -1; }
    ZSTD_inBuffer in = { src, srcn, 0 };
    while (in.pos < in.size) {
        if (cap - out->n < 131072) { cap = cap ? cap*2 + 131072 : 262144; out->p=xrealloc(out->p, cap); }
        ZSTD_outBuffer ob = { out->p + out->n, cap - out->n, 0 };
        size_t before = in.pos;
        r = Z.decompressStream(d, &ob, &in);
        out->n += ob.pos;
        if (Z.isError(r)) { if(errname)*errname=Z.getErrorName(r); Z.freeDStream(d); free(out->p); out->p=NULL; out->n=0; return -1; }
        if (ob.pos == 0 && in.pos == before && r != 0) { cap = cap ? cap*2 : 262144; out->p=xrealloc(out->p, cap); }
    }
    if (r != 0) { if(errname)*errname="truncated frame"; Z.freeDStream(d); free(out->p); out->p=NULL; out->n=0; return -1; }
    Z.freeDStream(d); return 0;
}

static int gzip_compress_buf(const unsigned char *src, size_t srcn, int level, struct buf *out) {
    z_stream s; memset(&s,0,sizeof(s));
    int zl = level; if (zl < 1) zl = 1; if (zl > 9) zl = 9;
    if (deflateInit2(&s, zl, Z_DEFLATED, 15+16, 8, Z_DEFAULT_STRATEGY) != Z_OK) return -1;
    size_t cap = compressBound(srcn) + 32; out->p=xmalloc(cap); out->n=0;
    s.next_in=(Bytef*)src; s.avail_in=(uInt)srcn; s.next_out=out->p; s.avail_out=(uInt)cap;
    int ret;
    while ((ret=deflate(&s, Z_FINISH)) == Z_OK) {
        size_t used = (size_t)(s.next_out - out->p); cap *= 2; out->p=xrealloc(out->p, cap); s.next_out=out->p+used; s.avail_out=(uInt)(cap-used);
    }
    if (ret != Z_STREAM_END) { deflateEnd(&s); free(out->p); return -1; }
    out->n = (size_t)(s.next_out - out->p); deflateEnd(&s); return 0;
}
static int gzip_decompress_buf(const unsigned char *src, size_t srcn, struct buf *out) {
    z_stream s; memset(&s,0,sizeof(s)); if (inflateInit2(&s, 15+32) != Z_OK) return -1;
    size_t cap = srcn*3 + 65536; out->p=xmalloc(cap); out->n=0;
    s.next_in=(Bytef*)src; s.avail_in=(uInt)srcn;
    int ret;
    do {
        if (cap - out->n < 65536) { cap = cap*2 + 65536; out->p=xrealloc(out->p, cap); }
        s.next_out=out->p+out->n; s.avail_out=(uInt)(cap-out->n);
        ret=inflate(&s, Z_NO_FLUSH); out->n=(size_t)(s.next_out-out->p);
    } while (ret == Z_OK);
    inflateEnd(&s);
    if (ret != Z_STREAM_END) { free(out->p); out->p=NULL; out->n=0; return -1; }
    return 0;
}

static const char *size_unit(unsigned long long n, char *tmp, size_t sz) {
    snprintf(tmp, sz, "%6llu B", n); return tmp;
}
static void success_compress_msg(const struct opts *o, const char *in, const char *outn, size_t isz, size_t osz) {
    if (o->quiet || o->stdout_mode) return;
    double pct = isz ? ((double)osz * 100.0 / (double)isz) : 0.0;
    char a[32], b[32];
    fprintf(stderr, "%-20s:%6.2f%%   (%s => %s, %s) \n", base_name(in), pct, size_unit(isz,a,sizeof(a)), size_unit(osz,b,sizeof(b)), outn);
}
static void success_decompress_msg(const struct opts *o, const char *in, size_t osz) {
    if (o->quiet || o->stdout_mode) return;
    fprintf(stderr, "%-20s: %llu bytes \n", base_name(in), (unsigned long long)osz);
}

static int has_zstd_magic(const unsigned char *p, size_t n) {
    return n>=4 && p[0]==0x28 && p[1]==0xb5 && p[2]==0x2f && p[3]==0xfd;
}
static int has_gzip_magic(const unsigned char *p, size_t n) { return n>=2 && p[0]==0x1f && p[1]==0x8b; }

static char *derive_decomp_name(const char *in, const struct opts *o) {
    if (endswith(in,".tzst")) return remove_suffix(in,".tzst"), append_suffix(remove_suffix(in,".tzst"), ".tar");
    if (endswith(in,".zst")) return remove_suffix(in,".zst");
    if (endswith(in,".zstd")) return remove_suffix(in,".zstd");
    if (endswith(in,".tgz")) { char *r=remove_suffix(in,".tgz"); char *t=append_suffix(r,".tar"); free(r); return t; }
    if (endswith(in,".gz")) return remove_suffix(in,".gz");
    msgerr(o,"zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n", in);
    return NULL;
}

static int frame_checksum_flag(const unsigned char *p, size_t n) {
    if (n < 5 || !has_zstd_magic(p,n)) return 0;
    return (p[4] & 4) ? 1 : 0;
}
static void print_list_for_file(const char *name, const struct opts *o) {
    struct buf in={0}; if(read_file(name,&in,o)!=0) return;
    load_zstd();
    unsigned long long totalu=0; size_t off=0; int frames=0; int check=0; unsigned lastchk=0;
    while (off < in.n) {
        size_t fs = Z.findFrameCompressedSize(in.p+off, in.n-off);
        if (Z.isError(fs)) break;
        unsigned long long u = Z.getFrameContentSize(in.p+off, fs);
        if (u==ZSTD_CONTENTSIZE_ERROR_ || u==ZSTD_CONTENTSIZE_UNKNOWN_) u=0;
        totalu += u; frames++; if(frame_checksum_flag(in.p+off,fs)) { check=1; if(fs>=4) lastchk=(unsigned)in.p[off+fs-4] | ((unsigned)in.p[off+fs-3]<<8) | ((unsigned)in.p[off+fs-2]<<16) | ((unsigned)in.p[off+fs-1]<<24); }
        off += fs;
    }
    if (o->verbose) {
        fprintf(stdout, "%s \n", name);
        fprintf(stdout, "# Zstandard Frames: %d\n", frames?frames:1);
        fprintf(stdout, "DictID: 0\n");
        fprintf(stdout, "Window Size: %llu B (%llu B)\n", totalu, totalu);
        fprintf(stdout, "Compressed Size: %llu B (%llu B)\n", (unsigned long long)in.n, (unsigned long long)in.n);
        fprintf(stdout, "Decompressed Size: %llu B (%llu B)\n", totalu, totalu);
        fprintf(stdout, "Ratio: %.4f\n", in.n?((double)totalu/(double)in.n):0.0);
        if (check) fprintf(stdout, "Check: XXH64 %08x\n\n", lastchk); else fprintf(stdout, "Check: None\n\n");
    } else {
        static int header=0; if(!header){ fputs("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename\n", stdout); header=1; }
        fprintf(stdout, "%6d      0  %6llu   B  %8llu   B  %5.3f  %5s  %s\n", frames?frames:1, (unsigned long long)in.n, totalu, in.n?((double)totalu/(double)in.n):0.0, check?"XXH64":" None", name);
    }
    free(in.p);
}

static int process_one(const char *name, const struct opts *o) {
    struct buf in={0}, out={0}; int rc=0; int input_stdin = strcmp(name,"-")==0;
    if (read_file(name,&in,o)!=0) return 1;
    if (o->decompress || o->test) {
        const char *err=NULL;
        int dres;
        if (has_gzip_magic(in.p,in.n)) dres = gzip_decompress_buf(in.p,in.n,&out);
        else dres = zstd_decompress_buf(in.p,in.n,&out,&err);
        if (dres != 0) {
            if (o->pass_through && o->force && !o->test) { out.p=in.p; out.n=in.n; in.p=NULL; dres=0; }
            else { msgerr(o,"zstd: %s: unknown header \n", input_stdin?"/*stdin*\\":name); free(in.p); return 1; }
        }
        if (o->test) { success_decompress_msg(o,name,out.n); free(in.p); free(out.p); return 0; }
        char *outname=NULL;
        if (o->stdout_mode || input_stdin) outname=xstrdup("-");
        else if (o->output) outname=xstrdup(o->output);
        else outname=derive_decomp_name(name,o);
        if(!outname){ free(in.p); free(out.p); return 1; }
        int w = write_file_all(outname,out.p,out.n,o);
        if (w==0) { success_decompress_msg(o,name,out.n); if(o->rm && !input_stdin && strcmp(outname,"-")!=0) unlink(name); }
        else rc=1;
        free(outname);
    } else {
        if (o->format_gzip) rc = gzip_compress_buf(in.p,in.n,o->level,&out);
        else rc = zstd_compress_buf(in.p,in.n,o->level,o->checksum,&out);
        if (rc != 0) { msgerr(o,"zstd: compression error \n"); free(in.p); return 1; }
        char *outname=NULL;
        if (o->stdout_mode || input_stdin) outname=xstrdup("-");
        else if (o->output) outname=xstrdup(o->output);
        else outname=append_suffix(name, o->format_gzip ? ".gz" : ".zst");
        int w=write_file_all(outname,out.p,out.n,o);
        if(w==0){ success_compress_msg(o,name,outname,in.n,out.n); if(o->rm && !input_stdin && strcmp(outname,"-")!=0) unlink(name); }
        else rc=1;
        free(outname);
    }
    free(in.p); free(out.p); return rc?1:0;
}

static int parse_int(const char *s) { return (int)strtol(s,NULL,10); }
static int all_digits(const char *s) { if(!*s) return 0; for(;*s;s++) if(!isdigit((unsigned char)*s)) return 0; return 1; }

static int need_arg(int *i, int argc, char **argv, const struct opts *o, char **dst) {
    if (*i+1 >= argc) { msgerr(o,"error: missing command argument \n"); return -1; }
    *dst = xstrdup(argv[++(*i)]); return 0;
}

static int parse_args(int argc, char **argv, struct opts *o) {
    memset(o,0,sizeof(*o)); o->level=3; o->checksum=1;
    const char *bn=base_name(argv[0]);
    if (strstr(bn,"unzstd")) o->decompress=1;
    if (strstr(bn,"zstdcat")) { o->decompress=1; o->stdout_mode=1; }
    for (int i=1;i<argc;i++) {
        char *a=argv[i];
        if (strcmp(a,"--")==0) { while(++i<argc) strv_push(&o->files,argv[i]); break; }
        if (strcmp(a,"-")==0 || a[0]!='-') { strv_push(&o->files,a); continue; }
        if (a[1]=='-' && a[2]) {
            if (!strcmp(a,"--help")) { print_full_help(stdout); exit(0); }
            else if (!strcmp(a,"--version")) { fputs(VERSION_LINE, stdout); exit(0); }
            else if (!strcmp(a,"--decompress")) o->decompress=1;
            else if (!strcmp(a,"--stdout")) o->stdout_mode=1;
            else if (!strcmp(a,"--force")) o->force=1;
            else if (!strcmp(a,"--keep")) o->rm=0;
            else if (!strcmp(a,"--rm")) o->rm=1;
            else if (!strcmp(a,"--quiet")) o->quiet++;
            else if (!strcmp(a,"--verbose")) o->verbose++;
            else if (!strcmp(a,"--check")) o->checksum=1;
            else if (!strcmp(a,"--no-check")) o->checksum=0;
            else if (!strcmp(a,"--test")) { o->test=1; o->decompress=1; }
            else if (!strcmp(a,"--list")) o->list=1;
            else if (!strcmp(a,"--ultra")) o->ultra=1;
            else if (!strcmp(a,"--pass-through")) o->pass_through=1;
            else if (!strcmp(a,"--no-pass-through")) o->pass_through=0;
            else if (!strcmp(a,"--progress")) o->progress=1;
            else if (!strcmp(a,"--no-progress")) o->progress=0;
            else if (!strcmp(a,"--format=zstd")) o->format_gzip=0;
            else if (!strcmp(a,"--format=gzip")) o->format_gzip=1;
            else if (!strncmp(a,"--fast",6)) {
                if (a[6]==0) o->level=-1;
                else if (a[6]=='=' && all_digits(a+7)) o->level = -parse_int(a+7);
                else { msgerr(o,"Incorrect parameter: %s \n", a); print_short_help(stderr); return -1; }
            }
            else if (!strncmp(a,"--format=",9)) { msgerr(o,"Incorrect parameter: %s \n", a); return -1; }
            else if (!strncmp(a,"--long",6) || !strncmp(a,"--adapt",7) || !strncmp(a,"--rsyncable",11) || !strncmp(a,"--jobsize=",10) || !strncmp(a,"--stream-size=",14) || !strncmp(a,"--size-hint=",12) || !strncmp(a,"--target-compressed-block-size=",31) || !strncmp(a,"--auto-threads=",15) || !strcmp(a,"--single-thread") || !strcmp(a,"--exclude-compressed") || !strcmp(a,"--sparse") || !strcmp(a,"--no-sparse") || !strcmp(a,"--asyncio") || !strcmp(a,"--no-asyncio") || !strcmp(a,"--no-dictID") || !strcmp(a,"--compress-literals") || !strcmp(a,"--no-compress-literals") || !strcmp(a,"--row-match-finder") || !strcmp(a,"--no-row-match-finder") || !strcmp(a,"--mmap-dict") || !strcmp(a,"--no-mmap-dict")) { /* accepted but ignored */ }
            else if (!strcmp(a,"--trace") || !strcmp(a,"--filelist") || !strcmp(a,"--output-dir-flat") || !strcmp(a,"--output-dir-mirror") || !strcmp(a,"--memory") || !strcmp(a,"--patch-from")) { char *tmp=NULL; if(need_arg(&i,argc,argv,o,&tmp)) return -1; free(tmp); }
            else if (!strncmp(a,"--trace=",8) || !strncmp(a,"--filelist=",11) || !strncmp(a,"--output-dir-flat=",18) || !strncmp(a,"--output-dir-mirror=",20) || !strncmp(a,"--memory=",9) || !strncmp(a,"--patch-from=",13)) { }
            else { msgerr(o,"Incorrect parameter: %s \n", a); print_short_help(stderr); return -1; }
            continue;
        }
        if (a[1] && all_digits(a+1)) {
            o->level=parse_int(a+1);
            if (o->level > 19 && !o->ultra) { if(!o->quiet) fputs("Warning : compression level higher than max, reduced to 19 \n", stderr); o->level=19; }
            continue;
        }
        for (int j=1; a[j]; j++) {
            char c=a[j];
            if (c=='h') { print_short_help(stdout); exit(0); }
            else if (c=='H') { print_full_help(stdout); exit(0); }
            else if (c=='V') { fputs(VERSION_LINE, stdout); exit(0); }
            else if (c=='d') o->decompress=1;
            else if (c=='c') o->stdout_mode=1;
            else if (c=='f') o->force=1;
            else if (c=='k') o->rm=0;
            else if (c=='q') o->quiet++;
            else if (c=='v') o->verbose++;
            else if (c=='r') { }
            else if (c=='l') o->list=1;
            else if (c=='t') { o->test=1; o->decompress=1; }
            else if (c=='S') { }
            else if (c=='o') { if(a[j+1]) { free(o->output); o->output=xstrdup(a+j+1); j=(int)strlen(a)-1; } else { if(need_arg(&i,argc,argv,o,&o->output)) return -1; } }
            else if (c=='D') { if(a[j+1]) { j=(int)strlen(a)-1; } else { char *tmp=NULL; if(need_arg(&i,argc,argv,o,&tmp)) return -1; free(tmp); } }
            else if (c=='T' || c=='M' || c=='b' || c=='e' || c=='i') { if(a[j+1]) { j=(int)strlen(a)-1; } }
            else { char bad[8]; snprintf(bad,sizeof(bad),"-%c",c); msgerr(o,"Incorrect parameter: %s \n", bad); print_short_help(stderr); return -1; }
        }
    }
    return 0;
}

int main(int argc, char **argv) {
    struct opts o; if (parse_args(argc,argv,&o)!=0) return 1;
    if (o.verbose && !o.list && !o.quiet) fputs(VERSION_LINE, stderr);
    if (o.files.n==0) strv_push(&o.files,"-");
    if (o.output && o.files.n > 1 && !o.stdout_mode) {
        msgerr(&o,"zstd: WARNING: all input files will be processed and concatenated into a single output file: %s \n", o.output);
        msgerr(&o,"The concatenated output CANNOT regenerate original file names nor directory structure. \nProceed? (y/n): Aborting... \n");
        return 1;
    }
    if (o.list) {
        if (o.verbose && !o.quiet) fputs(VERSION_LINE, stderr);
        for(int i=0;i<o.files.n;i++) print_list_for_file(o.files.v[i],&o);
        return 0;
    }
    int rc=0;
    for(int i=0;i<o.files.n;i++) if(process_one(o.files.v[i],&o)!=0) rc=1;
    return rc;
}
